WITH UserPosts AS (SELECT p.OwnerUserId, p.PostTypeId, COUNT(p.Id) AS TotalPosts, SUM(CASE WHEN p.Score > 0 THEN 1 ELSE 0 END) AS PositivePosts, SUM(CASE WHEN p.Score < 0 THEN 1 ELSE 0 END) AS NegativePosts FROM Posts AS p GROUP BY p.OwnerUserId, p.PostTypeId), UserReputation AS (SELECT u.Id AS UserId, u.Reputation, ROW_NUMBER() OVER (ORDER BY u.Reputation DESC NULLS FIRST) AS Rank, CASE WHEN u.Reputation < 1000 THEN 'Newbie' WHEN u.Reputation < 5000 THEN 'Intermediate' ELSE 'Expert' END AS UserLevel FROM Users AS u), PostDetails AS (SELECT p.Id AS PostId, p.OwnerUserId, p.Title, p.CreationDate, p.Score, COALESCE(ph.CreationDate, p.CreationDate) AS LastEditDate, CASE WHEN p.PostTypeId = 1 THEN 'Question' WHEN p.PostTypeId = 2 THEN 'Answer' ELSE 'Other' END AS PostType, (SELECT COUNT(c.Id) FROM Comments AS c WHERE c.PostId = p.Id) AS CommentCount FROM Posts AS p LEFT JOIN PostHistory AS ph ON p.Id = ph.PostId AND ph.PostHistoryTypeId IN (4, 5, 6)) SELECT up.OwnerUserId AS UserId, ur.Reputation, ur.UserLevel, SUM(up.TotalPosts) AS TotalPosts, SUM(up.PositivePosts) AS TotalPositivePosts, SUM(up.NegativePosts) AS TotalNegativePosts, GROUP_CONCAT(CONCAT(COALESCE(pd.Title, ''), ' (', COALESCE(pd.PostType, ''), ')'), '; ') AS PostTitles, AVG(COALESCE(pd.CommentCount, 0)) AS AverageCommentsPerPost, COUNT(DISTINCT pd.PostId) AS UniquePostCount FROM UserPosts AS up JOIN UserReputation AS ur ON up.OwnerUserId = ur.UserId LEFT JOIN PostDetails AS pd ON up.OwnerUserId = pd.OwnerUserId GROUP BY up.OwnerUserId, ur.Reputation, ur.UserLevel HAVING COUNT(DISTINCT pd.PostId) > 0 ORDER BY ur.Reputation DESC NULLS FIRST